// Level filter, then intake exclusions (lib-config). An alert whose level is
// missing or not numeric is not filtered here: pb-generic's normalizer parks it.
const alert = $('Intake input').first().json.alert;
const cfg = $input.first().json;
const rule = alert !== null && typeof alert === 'object' ? alert.rule : undefined;
const raw = rule !== null && typeof rule === 'object' ? rule.level : undefined;
const level = typeof raw === 'number' && Number.isInteger(raw) ? raw
  : typeof raw === 'string' && /^\d+$/.test(raw.trim()) ? Number(raw.trim()) : null;
const groups = rule !== null && typeof rule === 'object' && Array.isArray(rule.groups) ? rule.groups : [];
let decision = 'handoff';
let status = 'handed off to the router';
if (level !== null && level < cfg.min_level) {
  decision = 'filtered';
  status = `filtered: level ${level} < ${cfg.min_level}`;
} else {
  const ex = cfg.intake_exclusions.find((e) => groups.includes(e.rule_group));
  if (ex) { decision = 'skipped'; status = `skipped: ${ex.label}`; }
}
return [{ json: {
  decision, status,
  wazuh_alert_id: typeof alert?.id === 'string' ? alert.id : null,
  rule_id: rule?.id ?? null, rule_level: level,
  alert, config: cfg, recv_execution_id: $execution.id,
} }];

// The route is recorded here (this execution is saved) and passed to the
// playbook, which puts it in TheHive (caseTemplate, writeback).
const d = $('Intake decision').first().json;
const route = $input.first().json.route;
return [{ json: {
  status: `routed: ${route.route_id} -> ${route.playbook}` + (route.fallback ? ` (fallback from ${route.fallback.wanted})` : ''),
  route,
  wazuh_alert_id: d.wazuh_alert_id,
  alert: d.alert, config: d.config, recv_execution_id: d.recv_execution_id,
} }];

// lib-route-alert failed (a broken routing table in lib-config): park the
// alert with its id and payload, so it can be replayed once fixed.
const d = $('Intake decision').first().json;
const err = $input.first().json.error;
return [{ json: {
  error_class: 'unknown',
  stage: 'route',
  workflow: $workflow.name,
  execution_id: $execution.id,
  node: 'Route (lib-route-alert)',
  wazuh_alert_id: d.wazuh_alert_id,
  thehive_alert_id: null,
  message: 'routing failed: ' + (typeof err === 'string' ? err : err?.message ?? JSON.stringify($input.first().json).slice(0, 500)),
  payload: d.alert,
} }];
